const items = $input.all();
const vistas = {};
const linhas = [];

for (const item of items) {
  const tabela = item.json.tabela;
  if (!vistas[tabela]) {
    vistas[tabela] = true;
    linhas.push(`${tabela} - ${item.json.status}`);
  }
}

const data = new Date().toLocaleDateString('pt-BR');
const mensagem = `📊 *ETL Belga - ${data}*\n\n` + linhas.join('\n');
return [{ json: { mensagem } }];

